using Godot;
using System;

public partial class Main : Node
{
	// Called when the node enters the scene tree for the first time.
	public override void _Ready()
	{
	}

	// Called every frame. 'delta' is the elapsed time since the previous frame.
	public override void _Process(double delta)
	{
	}
}

public override void _Ready()
{
    GD.Print("Hello, Godot!");
    GD.Print("C# is working!");
    GD.Print($"Godot version: {Engine.GetVersionInfo()["string"]}");
}

private double _timer = 0;

public override void _Process(double delta)
{
    _timer += delta;
    if (_timer >= 3.0)
    {
        GD.Print("3 seconds have passed!");
        _timer = 0;
    }
}

public override void _Ready()
{
    GD.Print("About to cause an error...");
    int x = 0;
    int y = 10 / x;  // Division by zero!
}

// From the Main node, get the Player node
var player = GetNode<CharacterBody2D>("Player");

// From the Player node, get its Sprite2D child
var sprite = GetNode<Sprite2D>("Sprite2D");

// From the Player node, get the Enemy (sibling — go up, then down)
var enemy = GetNode<CharacterBody2D>("../Enemy");

// צעד ראשון: טעינת הסצנה ויצירת מופע
var bulletScene = GD.Load<PackedScene>("res://scenes/Bullet.tscn");
var bullet = bulletScene.Instantiate<Node2D>();

// צעד שני: הוספת המופע לעץ הסצנות כילד
bullet.Position = new Vector2(100, 200);
GetTree().CurrentScene.AddChild(bullet);

public partial class Player : CharacterBody2D
{
    // נטען פעם אחת בלבד כאשר הסקריפט נטען לשימוש בפעם הראשונה
    private readonly PackedScene _bulletScene = GD.Load<PackedScene>("res://scenes/Bullet.tscn");

    private void Shoot()
    {
        var bullet = _bulletScene.Instantiate<Node2D>();
        bullet.GlobalPosition = GlobalPosition;
        GetTree().CurrentScene.AddChild(bullet);
    }
}

// מוסיף כילד של נוד הבסיס בסצנה הנוכחית - הכי שכיח בשימוש
GetTree().CurrentScene.AddChild(bullet);

// מוסיף כילד של הנוד הנוכחי
AddChild(bullet);

